#!/usr/bin/env python3
"""Reconstruct the exact frozen v313; no solver runs and no eval registration."""
from pathlib import Path
import base64,difflib,hashlib,json,zlib
ROOT=Path(__file__).resolve().parents[2]
PARENT="c3f819c2715f397bee0ca95bca12be3196c6f5531dbfeb19358d0afd5f6868ea"
EXPECTED="19ed3103b15d612b8089514ee71147cf290a667c0761b7b3fca11ab154ab8b82"
PAYLOAD=""

def main():
    source=ROOT/'src/bin/v311_neural_multistart.cpp'
    original=source.read_bytes()
    if hashlib.sha256(original).hexdigest()!=PARENT:
        raise SystemExit('Parent hash mismatch; refusing to modify a different v311')
    lines=original.decode().splitlines(True)
    for first,last,replacement in reversed(json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))):
        lines[first:last]=replacement
    result=''.join(lines).encode()
    if hashlib.sha256(result).hexdigest()!=EXPECTED:raise SystemExit('Output hash mismatch')
    output=ROOT/'src/bin/v313_neural_rollout_grafting.cpp'
    output.write_bytes(result)
    patch=ROOT/'adhoc/v313/v313_vs_v311.patch';patch.parent.mkdir(parents=True,exist_ok=True)
    patch.write_text(''.join(difflib.unified_diff(original.decode().splitlines(True),result.decode().splitlines(True),fromfile='a/src/bin/v311_neural_multistart.cpp',tofile='b/src/bin/v313_neural_rollout_grafting.cpp')))
    print(EXPECTED,output)
if __name__=='__main__':main()
